{
  "spans": [
    {
      "label": "QUOTE",
      "frame": "དེའི་ལན།",
      "head": "དཀར་གསུམ་མངར་གསུམ་ལན་ཚ་དྲི། །སྡིག་མེད་འབྲས་བུ་ང་ཡི་ཟས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "གསུངས་པ།",
      "head": "འོ་སྐོལ་སྤྲེའུ་རྣམས་ཉོན་ཅིག ཕྱི་སྣང་བ་འབྲལ་མེད་འདི་ལྟ་བ། ནང་རིག་པ་འཛིན་མེད་འདི་སྒོམ་པ། བར་བླང་དོར་མེད་པ་འདི་སྤྱོད་པ་ཡིན།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སྤྲེའུས་སྨྲས་པ།",
      "head": "རིགས་ཀྱི་མཆོག་གྱུར་རྒྱལ་པོ་བདག་ལ་གསོན། ། རྒྱུ་འབྲས་རྟེན་འབྲེལ་འབྱུང་བ་ནི། །",
      "tail": "རྫུན་པ་ཡིན་ན་སྤྲེའུ་ཤི། །"
    },
    {
      "label": "QUOTE",
      "frame": "སྨྲས་པ།",
      "head": "རང་ཅག་སྤྲེའུ་ཐམས་ཅད་ཀུན། ། སྣང་བ་ཇི་ལྟར་སྣང་ཡང་རུང༌། །",
      "tail": "འོད་གསལ་ཆོས་སྐུ་ཆེན་པོར་ཞོག །"
    },
    {
      "label": "QUOTE",
      "frame": "གཅིག་ན་རེ།",
      "head": "ཚེ་ལ་ལོང་མེད་ཡུན་རིང་མི་སྡོད་ངེས། ། ཐོས་པས་མཐའ་ཆོག་རིག་པ་ནང་དུ་ཁུག །",
      "tail": "འཁོར་བ་སྤངས་ནས་མྱང་འདས་བསྒྲུབ་ཏུ་མེད། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཁོང་ན་རེ།",
      "head": "ནགས་ཚལ་མཐོང་དུ་བསྒོམ་ན་བདེ་བ་ཐོབ། །ཐམས་ཅད་སེམས་སུ་ཤེས་པས་མཐུན་པར་གསུངས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ན་རེ།",
      "head": "དྲན་པ་རང་སངས་ཆུ་ཡི་རི་མོ་འདྲ། ། འགག་པ་མེད་པ་ཉི་མའི་སྙིང་པོ་འདྲ། །",
      "tail": "གསལ་ལ་མ་འགག་ཤེལ་གྱི་སྒོ་ང་འདྲ། །"
    },
    {
      "label": "QUOTE",
      "frame": "མོ་ན་རེ།",
      "head": "བྱམས་དང་སྙིང་རྗེ་བྱང་ཆུབ་སེམས་དཔའ། ། བསྒོམས་ན་རང་ཉིད་ཐུགས་རྗེ་ཆེ། །",
      "tail": "སྙིང་རྗེ་ཟུང་འཇུག་སྤྱན་རས་གཟིགས། །"
    },
    {
      "label": "QUOTE",
      "frame": "འདི་སྐད་སྨྲས་སོ། །",
      "head": "ལྷའམ་ཀླུའམ་གནོད་སྦྱིན་གང་གི་བུ། ། པདྨ་ལས་སྐྱེས་པདྨ་ལས་འཁྲུངས་ཏེ། །",
      "tail": "བདག་གི་སྲས་བྱ་ཁང་བཟང་དམ་པར་གཤེགས། །"
    },
    {
      "label": "QUOTE",
      "frame": "ཟེར་ནས་",
      "head": "སྐྱེ་བ་མང་པོའི་སྔོན་རོལ་ཏུ། ། ལས་ངན་གཅིག་གི་རྣམ་སྨིན་ཡིན། །",
      "tail": ""
    }
  ]
}
